<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Personal Expense Tracker</title>
    <style>
        body { font-family: sans-serif; max-width: 600px; margin: 2rem auto; padding: 0 1rem; }
        form { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 2rem; }
        form button { grid-column: span 2; }
        input, select { width: 100%; padding: 5px; }
        .full-row { grid-column: span 2; }
        button { padding: 8px; cursor: pointer; background: #333; color: white; border: none; }
        #form-error { color: red; margin-top: 5px; min-height: 1.2em; font-size: 0.9em; }
        #filters { border-bottom: 1px solid #ccc; padding: 10px 0; margin-bottom: 1rem; display: flex; gap: 10px; flex-wrap: wrap; }
        #filters * { width: auto; }
        #summary { margin-bottom: 1rem; font-weight: bold; }
        .cat-summary { font-size: 0.9em; color: #555; }
        ul { list-style: none; padding: 0; }
        li.expense { display: flex; justify-content: space-between; align-items: center; padding: 10px; border-bottom: 1px solid #eee; }
        li.expense button.exp-del { background: red; padding: 4px 8px; font-size: 0.8em; }
        li.expense.hidden { display: none; }
        .category-totals { display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 1rem; }
        .cat-total { background: #f9f9f9; padding: 5px 10px; border-radius: 4px; }
    </style>
</head>
<body>
    <form id="expense-form">
        <input type="number" id="amount" placeholder="Amount" step="0.01">
        <select id="category">
            <option value="groceries">groceries</option>
            <option value="transport">transport</option>
            <option value="bills">bills</option>
            <option value="fun">fun</option>
        </select>
        <input type="date" id="date" class="full-row">
        <input type="text" id="note" placeholder="Note (optional)" class="full-row">
        <button type="submit" id="add-expense">Add Expense</button>
        <div id="form-error"></div>
    </form>

    <div id="filters">
        <select id="filter-category">
            <option value="all">all</option>
            <option value="groceries">groceries</option>
            <option value="transport">transport</option>
            <option value="bills">bills</option>
            <option value="fun">fun</option>
        </select>
        <input type="date" id="filter-from" title="From Date">
        <input type="date" id="filter-to" title="To Date">
    </div>

    <div id="summary">
        Total: <span id="total">0.00</span>
        <div class="category-totals" id="cat-summary-container">
            <!-- cat-total elements injected here -->
        </div>
    </div>

    <ul id="expense-list"></ul>

    <script>
        const STORAGE_KEY = 'expense_tracker_data';
        const categories = ['groceries', 'transport', 'bills', 'fun'];
        let expenses = [];

        // DOM elements
        const form = document.getElementById('expense-form');
        const amountInput = document.getElementById('amount');
        const errorDiv = document.getElementById('form-error');
        const listEl = document.getElementById('expense-list');
        const totalEl = document.getElementById('total');
        const catSummaryContainer = document.getElementById('cat-summary-container');
        const filterCat = document.getElementById('filter-category');
        const filterFrom = document.getElementById('filter-from');
        const filterTo = document.getElementById('filter-to');

        // Load from localStorage
        function loadExpenses() {
            const data = localStorage.getItem(STORAGE_KEY);
            if (data) expenses = JSON.parse(data);
        }

        // Save to localStorage
        function saveExpenses() {
            localStorage.setItem(STORAGE_KEY, JSON.stringify(expenses));
        }

        // Initialize category summary elements
        function initCategorySummaries() {
            catSummaryContainer.innerHTML = '';
            categories.forEach(cat => {
                const span = document.createElement('span');
                span.className = 'cat-total';
                span.setAttribute('data-cat', cat);
                span.textContent = `${cat}: 0.00`;
                catSummaryContainer.appendChild(span);
            });
        }

        // Get filtered expenses
        function getFilteredExpenses() {
            const catVal = filterCat.value;
            const fromVal = filterFrom.value;
            const toVal = filterTo.value;

            return expenses.filter(e => {
                const catMatch = (catVal === 'all' || e.category === catVal);
                const fromMatch = (!fromVal || e.date >= fromVal);
                const toMatch = (!toVal || e.date <= toVal);
                return catMatch && fromMatch && toMatch;
            });
        }

        // Update summary totals based on filtered expenses
        function updateSummaries(visible) {
            const total = visible.reduce((sum, e) => sum + parseFloat(e.amount), 0);
            totalEl.textContent = total.toFixed(2);

            categories.forEach(cat => {
                const catTotal = visible
                    .filter(e => e.category === cat)
                    .reduce((sum, e) => sum + parseFloat(e.amount), 0);
                const el = document.querySelector(`.cat-total[data-cat="${cat}"]`);
                if (el) el.textContent = `${cat}: ${catTotal.toFixed(2)}`;
            });
        }

        // Render list
        function render() {
            const visible = getFilteredExpenses();
            listEl.innerHTML = '';

            visible.forEach(e => {
                const li = document.createElement('li');
                li.className = 'expense';
                li.dataset.id = e.id;
                li.innerHTML = `
                    <span>
                        <strong>$${parseFloat(e.amount).toFixed(2)}</strong> 
                        <em>(${e.category})</em> 
                        <small>${e.date}</small> 
                        ${e.note ? `<small> - ${e.note}</small>` : ''}
                    </span>
                    <button class="exp-del">Del</button>
                `;
                listEl.appendChild(li);
            });

            updateSummaries(visible);
        }

        // Event: Add Expense
        form.addEventListener('submit', (e) => {
            e.preventDefault();
            const amountVal = amountInput.value.trim();
            const dateVal = document.getElementById('date').value;

            // Validation
            if (!amountVal || isNaN(parseFloat(amountVal)) || parseFloat(amountVal) <= 0) {
                errorDiv.textContent = 'Please enter a valid positive amount.';
                return;
            }
            if (!dateVal) {
                errorDiv.textContent = 'Please select a date.';
                return;
            }

            errorDiv.textContent = '';

            const newExpense = {
                id: Date.now(),
                amount: amountVal,
                category: document.getElementById('category').value,
                date: dateVal,
                note: document.getElementById('note').value.trim()
            };

            expenses.push(newExpense);
            saveExpenses();

            // Reset form
            amountInput.value = '';
            document.getElementById('note').value = '';
            render();
        });

        // Event: Filter Changes
        filterCat.addEventListener('change', render);
        filterFrom.addEventListener('change', render);
        filterTo.addEventListener('change', render);

        // Event: List (Delegation for delete)
        listEl.addEventListener('click', (e) => {
            if (e.target.classList.contains('exp-del')) {
                const id = parseInt(e.target.closest('.expense').dataset.id);
                expenses = expenses.filter(e => e.id !== id);
                saveExpenses();
                render();
            }
        });

        // Init
        loadExpenses();
        initCategorySummaries();
        render();
    </script>
</body>
</html>
